mapper.select:
SELECT scheduled_id, scheduled_name, scheduled_type, cron_expression, target_system, target_interface, status, last_run_time, next_run_time, create_by, create_time, update_by, update_time FROM finance_scheduled
AND scheduled_name LIKE '%' || #{params.scheduledName} || '%'
AND scheduled_type = #{params.scheduledType}
AND target_system = #{params.targetSystem}
AND status = #{params.status}
ORDER BY create_time DESC

mapper.update:
UPDATE finance_scheduled SET status = #{params.status},
last_run_time = SYSDATE,
update_time = SYSDATE WHERE scheduled_id = #{params.scheduledId}

mapper.select:
SELECT history_id, scheduled_id, scheduled_name, execute_time, execute_status, execute_result, error_message, execute_duration FROM finance_scheduled_history
AND scheduled_id = #{params.scheduledId}
AND execute_status = #{params.executeStatus}
ORDER BY execute_time DESC
